#!/bin/sh
# Stands in for Apollo codegen: ONE whole-schema invocation whose output is source for
# SEVERAL targets, and not decomposable per target. The operation set is discovered by
# scanning, so the generated file *set* is not knowable from the manifest.
#
# Environment for a multi-target generator, which has one output directory per consumer,
# named in a file rather than in variables because the consumers are not known here:
#
#   TUIST_INPUTS_FILE   JSON array of {type, path}
#   TUIST_OUTPUTS_FILE  JSON array of {project, target, path}, one entry per declared
#                       output. An array rather than an object keyed by target, because
#                       target names are not unique across projects.
#   TUIST_TARGET_NAME   this codegen target's own name
#   TUIST_ROOT_DIR      repo root
#   TUIST_PROJECT_DIR   the project directory, NOT the repo root
#
# A wrapper script rather than `apollo-ios-cli` directly, and that is inherent to the tool:
# it takes a single JSON configuration naming its own output paths, so something has to
# reconcile that configuration with the directories Tuist assigned.
#
# Consuming the pre-expanded glob rather than re-running `find` is the point of
# $TUIST_INPUTS_FILE: the files hashed for the cache key and the files actually read are
# the same set by construction.
set -e

VERSION="1.0.0"
if [ "$1" = "--version" ]; then echo "fixture-apollo $VERSION"; exit 0; fi

: "${TUIST_INPUTS_FILE:?must be set}"
: "${TUIST_OUTPUTS_FILE:?must be set}"

# Outputs are looked up by target rather than by position, so reordering `outputs:` in the
# manifest cannot silently redirect a consumer's generated sources.
eval "$(/usr/bin/python3 -c '
import json, shlex, sys
outputs = json.load(open(sys.argv[1]))
def path_for(target):
    return next((e["path"] for e in outputs if e["target"] == target), "")
print("SCHEMA_OUT=" + shlex.quote(path_for("GQLSchema")))
print("TYPES_OUT=" + shlex.quote(path_for("GQLTypes")))
' "$TUIST_OUTPUTS_FILE")"

[ -n "$SCHEMA_OUT" ] || { echo "error: no output declared for GQLSchema" >&2; exit 1; }
[ -n "$TYPES_OUT" ] || { echo "error: no output declared for GQLTypes" >&2; exit 1; }

# The `.glob("//Projects/**/*.graphql")` input arrives already expanded to one absolute
# path per matched file, so operations are partitioned out of the declared set rather than
# rediscovered by walking the tree.
SCHEMA=""
OPERATIONS=""
while IFS= read -r INPUT; do
    case "$INPUT" in
        *.graphqls) SCHEMA="$INPUT" ;;
        *.graphql)  OPERATIONS="$OPERATIONS$INPUT
" ;;
    esac
done <<EOF
$(/usr/bin/python3 -c 'import json,sys
for e in json.load(open(sys.argv[1])): print(e["path"])' "$TUIST_INPUTS_FILE")
EOF

[ -f "$SCHEMA" ] || { echo "error: no .graphqls schema among declared inputs" >&2; exit 1; }

cat > "$SCHEMA_OUT/SchemaMetadata.generated.swift" <<EOF
// AUTO-GENERATED by apollo.sh $VERSION. DO NOT EDIT.
public enum SchemaMetadata { public static let version = "$VERSION" }
EOF

# One type per `type` in the schema: adding a type changes the generated file set.
grep '^type ' "$SCHEMA" | awk '{print $2}' | while read -r NAME; do
    cat > "$TYPES_OUT/$NAME.generated.swift" <<EOF
// AUTO-GENERATED by apollo.sh $VERSION. DO NOT EDIT.
public struct $NAME: Sendable { public init() {} }
EOF
done

# One type per discovered operation. Adding a .graphql anywhere in the repo changes the
# file set too, which is why the manifest declares the glob repo-wide (`//Projects/**`).
printf '%s' "$OPERATIONS" | while IFS= read -r OP; do
    [ -n "$OP" ] || continue
    OP_NAME=$(basename "$OP" .graphql)
    cat > "$TYPES_OUT/$OP_NAME.generated.swift" <<EOF
// AUTO-GENERATED by apollo.sh $VERSION from $(basename "$OP"). DO NOT EDIT.
public struct $OP_NAME: Sendable {
    public static let operationName = "$OP_NAME"
    public init() {}
}
EOF
done
